    input  logic        rst_n,
    input  logic        start,
    input  logic        ack,
    output logic        tRCD_done
);

    // ---------------------------------------------------------
    // State type
    // ---------------------------------------------------------
    typedef enum logic [1:0] {
        IDLE                 = 2'd0,
        COUNTING             = 2'd1,
