// ============================================================
// Auto-generated by fsm_generator.py -- DO NOT EDIT
// Design : ddr4_bank_activate_fsm
// States : IDLE, COUNTING, DONE
// Reset  : rst_n (sync)
// Regenerate: python3 fsm_generator.py <spec>.yaml
// ============================================================

module ddr4_bank_activate_fsm (
    input  logic        clk,
    input  logic        rst_n,
    input  logic        start,
    input  logic        ack,
    output logic        tRCD_done
);

    // ---------------------------------------------------------
    // State type
    // ---------------------------------------------------------
    typedef enum logic [1:0] {
        IDLE                 = 2'd0,
        COUNTING             = 2'd1,
        DONE                 = 2'd2
    } state_t;

    state_t current_state, next_state;

    // ---------------------------------------------------------
    // Counters (auto-sized from transition conditions)
    // ---------------------------------------------------------
    logic [4:0] tRCD_counter;  // 5 bit(s), holds up to 31
    localparam int TRCD_COUNTER_WIDTH = $bits(tRCD_counter);
    localparam logic [TRCD_COUNTER_WIDTH-1:0] TRCD_COUNTER_ZERO_L = TRCD_COUNTER_WIDTH'(0);
    localparam logic [TRCD_COUNTER_WIDTH-1:0] TRCD_COUNTER_ONE_L = TRCD_COUNTER_WIDTH'(1);

    // ---------------------------------------------------------
    // State register  (sync reset)
    // ---------------------------------------------------------
    always_ff @(posedge clk) begin
        if (!rst_n) begin
            current_state <= IDLE;
            tRCD_counter <= TRCD_COUNTER_ZERO_L;
        end else begin
            current_state <= next_state;
            // Reset counters on any state change;
            // increment only in the state the counter belongs to.
            if (current_state != next_state) begin
                tRCD_counter <= TRCD_COUNTER_ZERO_L;
            end else begin
                if (current_state == COUNTING) begin
                    tRCD_counter <= tRCD_counter + TRCD_COUNTER_ONE_L;
                end
            end
        end
    end

    // ---------------------------------------------------------
    // Next-state logic
    // ---------------------------------------------------------
